import{Z as t,e as a,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const f=JSON.parse('{"title":"Salesflare","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/salesflare.md","filePath":"integrations/crm/salesflare.md","lastUpdated":1780377007000}'),i={name:"integrations/crm/salesflare.md"};function r(s,e,l,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="salesflare" tabindex="-1">Salesflare <a class="header-anchor" href="#salesflare" aria-label="Permalink to &quot;Salesflare&quot;">​</a></h1><p>Connect Salesflare to send enquiries to the records your team manages. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Salesflare as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-salesflare-api" tabindex="-1">Step 2. Connect to the Salesflare API <a class="header-anchor" href="#step-2-connect-to-the-salesflare-api" aria-label="Permalink to &quot;Step 2. Connect to the Salesflare API&quot;">​</a></h3><ol><li>Go to <a href="https://salesflare.com/" target="_blank">Salesflare</a> and login to your account.</li><li>In the left-hand sidebar menu, click the <strong>Settings</strong> icon.</li><li>In the left-hand sidebar sub-menu, click on <strong>API Keys</strong>.</li><li>Click on the large <strong>+</strong> add button in the bottom-right of the screen.</li><li>Copy the <strong>API Key</strong> from Salesflare and paste in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the record types this integration exposes, then map the required destination fields using the variable picker. For a contact enquiry, map the visitor’s email and name where those fields are available. Use the requirements shown for your selected record type rather than assuming every CRM accepts the same fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the test record in the selected CRM destination. Check the mapped values and whether the integration created a record or updated an existing one as intended.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const p=t(i,[["render",r]]);export{f as __pageData,p as default};
